package dev.abros.rivet.core.skins;
import dev.abros.rivet.core.*;
import com.google.gson.*;
import java.util.*;
/** Shared lock makes ownership, quota checks and reference cleanup atomic. */
public final class SkinStore {
 private final PgDatabase db;private final SkinSettings settings;
 public SkinStore(PgDatabase db,SkinSettings settings){this.db=db;this.settings=settings;}
 public JsonObject mutate(UUID owner,String op,JsonObject input,byte[] bytes)throws Exception{
  var receipt=input.deepCopy();receipt.addProperty("scope","skins");receipt.addProperty("op",op);if(bytes!=null)receipt.addProperty("hash",Hashes.sha256(bytes));
  return db.communityTransaction(()->new RequestJournal(db).execute(owner.toString(),receipt,()->{
   lock();db.lock("capes");var undo=new AppearanceUndo(db,settings);var before=undo.snapshot(owner);
   switch(op){case "appearanceUndo"->undo.restore(owner);case "outfitSave","outfitDelete","outfitSelect"->new OutfitStore(db,settings).mutate(owner,op,input);case "capeUpload","capeSelect","capeDelete","capeHide"->new CapeStore(db,settings).mutate(owner,op,input,bytes);case "undo"->undo(owner);case "upload"->upload(owner,Json.str(input,"name"),input.get("slim").getAsBoolean(),bytes);case "moveUp","moveDown"->move(owner,Json.str(input,"id"),op.equals("moveUp")?-1:1);case "rename"->rename(owner,Json.str(input,"id"),Json.str(input,"name"));case "select","delete","model"->change(owner,op,Json.opt(input,"id",""),input.has("slim")&&input.get("slim").getAsBoolean());default->throw new IllegalArgumentException("Unknown skin command");}
   if(Set.of("outfitSelect","capeUpload","capeSelect","capeHide","upload","select","model").contains(op))undo.remember(owner,before);else if(op.equals("undo"))undo.clear(owner);
   return library(owner);
  }));
 }
 private void lock()throws Exception{db.lock("skins");}
 private void profile(UUID owner)throws Exception{try(var q=db.connection().prepareStatement("INSERT INTO skin_profiles(owner) VALUES(?) ON CONFLICT DO NOTHING")){q.setObject(1,owner);q.executeUpdate();}}
 private void image(String hash,byte[] png)throws Exception{try(var q=db.connection().prepareStatement("INSERT INTO skin_images VALUES(?,?) ON CONFLICT DO NOTHING")){q.setString(1,hash);q.setBytes(2,png);q.executeUpdate();}}
 private void clean()throws Exception{try(var q=db.connection().createStatement()){q.executeUpdate("DELETE FROM skin_images i WHERE NOT EXISTS(SELECT 1 FROM skin_library l WHERE l.hash=i.hash) AND NOT EXISTS(SELECT 1 FROM skin_profiles p WHERE p.fallback=i.hash)");}}
 public JsonObject library(UUID owner)throws Exception{return db.communityTransaction(()->{var out=new JsonObject();out.addProperty("enabled",settings.enabled());out.addProperty("maxBytes",settings.maxBytes());out.addProperty("maxResolution",settings.maxResolution());out.addProperty("limit",settings.maxSkinsPerPlayer());var rows=new JsonArray();try(var q=db.connection().prepareStatement("SELECT id,hash,name,slim FROM skin_library WHERE owner=? ORDER BY position,name,id")){q.setObject(1,owner);try(var r=q.executeQuery()){while(r.next()){var row=new JsonObject();row.addProperty("id",r.getString(1));row.addProperty("hash",r.getString(2));row.addProperty("name",r.getString(3));row.addProperty("slim",r.getBoolean(4));rows.add(row);}}}out.add("entries",rows);try(var q=db.connection().prepareStatement("SELECT undo_available FROM skin_profiles WHERE owner=?")){q.setObject(1,owner);try(var r=q.executeQuery()){out.addProperty("canUndo",r.next()&&r.getBoolean(1));}}out.addProperty("canUndoAppearance",new AppearanceUndo(db,settings).available(owner));out.add("outfits",new OutfitStore(db,settings).library(owner));out.addProperty("outfitLimit",settings.maxOutfitsPerPlayer());out.add("capes",new CapeStore(db,settings).library(owner));out.add("profile",appearance(owner));return out;});}
 public JsonObject appearance(UUID owner)throws Exception{return db.communityTransaction(()->{var out=new JsonObject();new CapeStore(db,settings).appearance(owner).entrySet().forEach(e->out.add(e.getKey(),e.getValue()));out.addProperty("owner",owner.toString());out.addProperty("active","");out.addProperty("hash","");out.addProperty("slim",false);out.addProperty("fallbackHash","");out.addProperty("fallbackSlim",false);try(var q=db.connection().prepareStatement("SELECT p.active,coalesce(l.hash,p.fallback),CASE WHEN l.id IS NULL THEN p.slim ELSE l.slim END,p.fallback,p.slim FROM skin_profiles p LEFT JOIN skin_library l ON l.id=p.active WHERE p.owner=?")){q.setObject(1,owner);try(var r=q.executeQuery()){if(r.next()){out.addProperty("active",Objects.toString(r.getString(1),""));out.addProperty("hash",Objects.toString(r.getString(2),""));out.addProperty("slim",r.getBoolean(3));out.addProperty("fallbackHash",Objects.toString(r.getString(4),""));out.addProperty("fallbackSlim",r.getBoolean(5));}}}return out;});}
 public byte[] capeBytes(String hash)throws Exception{return new CapeStore(db,settings).bytes(hash);}
 public byte[] bytes(String hash)throws Exception{if(!hash.matches("[0-9a-f]{64}"))throw new IllegalArgumentException("Invalid skin hash");return db.communityTransaction(()->{try(var q=db.connection().prepareStatement("SELECT png FROM skin_images WHERE hash=?")){q.setString(1,hash);try(var r=q.executeQuery()){if(!r.next())throw new IllegalArgumentException(dev.abros.rivet.core.Messages.text("rivet.core.skin_deleted_b2950d1b"));return r.getBytes(1);}}});}
 public void upload(UUID owner,String name,boolean slim,byte[] data)throws Exception{
  if(!settings.enabled())throw new IllegalArgumentException(dev.abros.rivet.core.Messages.text("rivet.core.skins_disabled_4c1f50ce"));if(name.isBlank()||name.length()>40||name.codePoints().anyMatch(Character::isISOControl))throw new IllegalArgumentException(dev.abros.rivet.core.Messages.text("rivet.core.name_1_40_characters_2e10bd2e"));
  byte[] png=SkinImage.normalize(data,settings.maxBytes(),settings.maxResolution());String hash=Hashes.sha256(png);
  db.communityTransaction(()->{lock();profile(owner);UUID id=null;int count=0;try(var q=db.connection().prepareStatement("SELECT id,hash FROM skin_library WHERE owner=?")){q.setObject(1,owner);try(var r=q.executeQuery()){while(r.next()){count++;if(hash.equals(r.getString(2)))id=r.getObject(1,UUID.class);}}}if(id==null){if(count>=settings.maxSkinsPerPlayer())throw new IllegalArgumentException(dev.abros.rivet.core.Messages.text("rivet.core.skin_limit_reached_f22449f3"));id=UUID.randomUUID();image(hash,png);try(var q=db.connection().prepareStatement("INSERT INTO skin_library(id,owner,hash,name,slim,position) VALUES(?,?,?,?,?,(SELECT coalesce(max(position),-1)+1 FROM skin_library WHERE owner=?))")){q.setObject(1,id);q.setObject(2,owner);q.setString(3,hash);q.setString(4,name);q.setBoolean(5,slim);q.setObject(6,owner);q.executeUpdate();}}else{rememberModel(owner,id,slim);try(var q=db.connection().prepareStatement("UPDATE skin_library SET slim=? WHERE id=?")){q.setBoolean(1,slim);q.setObject(2,id);q.executeUpdate();}}setActive(owner,id);return null;});
 }
 private void setActive(UUID owner,UUID id)throws Exception{try(var q=db.connection().prepareStatement("UPDATE skin_profiles SET undo_active=active,undo_slim=coalesce((SELECT slim FROM skin_library WHERE id=active),FALSE),undo_available=TRUE,active=? WHERE owner=? AND active IS DISTINCT FROM ?")){q.setObject(1,id);q.setObject(2,owner);q.setObject(3,id);q.executeUpdate();}}
 public void change(UUID owner,String op,String id,boolean slim)throws Exception{db.communityTransaction(()->{lock();if(!settings.enabled())throw new IllegalArgumentException(dev.abros.rivet.core.Messages.text("rivet.core.skins_disabled_4c1f50ce"));profile(owner);UUID key=id.isEmpty()?null:UUID.fromString(id);if(key==null){if(!op.equals("select"))throw new IllegalArgumentException(dev.abros.rivet.core.Messages.text("rivet.ui.select_a_skin_8e54dd75"));setActive(owner,null);return null;}try(var q=db.connection().prepareStatement("SELECT 1 FROM skin_library WHERE owner=? AND id=?")){q.setObject(1,owner);q.setObject(2,key);try(var r=q.executeQuery()){if(!r.next())throw new IllegalArgumentException(dev.abros.rivet.core.Messages.text("rivet.core.skin_not_found_efd2256f"));}}
  switch(op){case "select"->setActive(owner,key);case "model"->{rememberModel(owner,key,slim);try(var q=db.connection().prepareStatement("UPDATE skin_library SET slim=? WHERE id=?")){q.setBoolean(1,slim);q.setObject(2,key);q.executeUpdate();}}case "delete"->{try(var q=db.connection().prepareStatement("UPDATE skin_profiles SET undo_available=FALSE,undo_active=NULL WHERE owner=? AND (undo_active=? OR active=?)")){q.setObject(1,owner);q.setObject(2,key);q.setObject(3,key);q.executeUpdate();}try(var q=db.connection().prepareStatement("DELETE FROM skin_library WHERE id=?")){q.setObject(1,key);q.executeUpdate();}clean();}default->throw new IllegalArgumentException(dev.abros.rivet.core.Messages.text("rivet.core.unknown_action_ea069893"));}return null;});}
 private void rememberModel(UUID owner,UUID id,boolean slim)throws Exception{
  try(var q=db.connection().prepareStatement("UPDATE skin_profiles p SET undo_active=p.active,undo_slim=l.slim,undo_available=TRUE FROM skin_library l WHERE p.owner=? AND p.active=? AND l.id=p.active AND l.slim<>?")){q.setObject(1,owner);q.setObject(2,id);q.setBoolean(3,slim);q.executeUpdate();}
 }
 public void undo(UUID owner)throws Exception{db.communityTransaction(()->{
  lock();if(!settings.enabled())throw new IllegalArgumentException(Messages.text("rivet.core.skins_disabled_4c1f50ce"));
  UUID previous;boolean slim;
  try(var q=db.connection().prepareStatement("SELECT undo_active,undo_slim FROM skin_profiles WHERE owner=? AND undo_available")){q.setObject(1,owner);try(var r=q.executeQuery()){if(!r.next())throw new IllegalArgumentException(Messages.text("rivet.skin.undo.unavailable"));previous=r.getObject(1,UUID.class);slim=r.getBoolean(2);}}
  if(previous!=null)try(var q=db.connection().prepareStatement("UPDATE skin_library SET slim=? WHERE id=? AND owner=?")){q.setBoolean(1,slim);q.setObject(2,previous);q.setObject(3,owner);if(q.executeUpdate()!=1)throw new IllegalArgumentException(Messages.text("rivet.skin.undo.unavailable"));}
  try(var q=db.connection().prepareStatement("UPDATE skin_profiles SET active=?,undo_active=NULL,undo_available=FALSE WHERE owner=?")){q.setObject(1,previous);q.setObject(2,owner);q.executeUpdate();}return null;
 });}
 public void move(UUID owner,String id,int direction)throws Exception{
  if(direction!=1&&direction!=-1)throw new IllegalArgumentException("Invalid direction");
  db.communityTransaction(()->{lock();if(!settings.enabled())throw new IllegalArgumentException(dev.abros.rivet.core.Messages.text("rivet.core.skins_disabled_4c1f50ce"));var ids=new ArrayList<UUID>();try(var q=db.connection().prepareStatement("SELECT id FROM skin_library WHERE owner=? ORDER BY position,name,id")){q.setObject(1,owner);try(var r=q.executeQuery()){while(r.next())ids.add(r.getObject(1,UUID.class));}}int index=ids.indexOf(UUID.fromString(id));if(index<0)throw new IllegalArgumentException(dev.abros.rivet.core.Messages.text("rivet.core.skin_not_found_efd2256f"));int target=index+direction;if(target<0||target>=ids.size())return null;Collections.swap(ids,index,target);try(var q=db.connection().prepareStatement("UPDATE skin_library SET position=? WHERE owner=? AND id=?")){for(int i=0;i<ids.size();i++){q.setInt(1,i);q.setObject(2,owner);q.setObject(3,ids.get(i));q.addBatch();}q.executeBatch();}return null;});
 }
 public void rename(UUID owner,String id,String name)throws Exception{
  if(!settings.enabled())throw new IllegalArgumentException(dev.abros.rivet.core.Messages.text("rivet.core.skins_disabled_4c1f50ce"));
  name=name.strip();if(name.isBlank()||name.length()>40||name.codePoints().anyMatch(Character::isISOControl))throw new IllegalArgumentException(dev.abros.rivet.core.Messages.text("rivet.core.name_1_40_characters_2e10bd2e"));
  final String label=name;UUID key=UUID.fromString(id);
  db.communityTransaction(()->{lock();try(var q=db.connection().prepareStatement("UPDATE skin_library SET name=? WHERE owner=? AND id=?")){q.setString(1,label);q.setObject(2,owner);q.setObject(3,key);if(q.executeUpdate()!=1)throw new IllegalArgumentException(dev.abros.rivet.core.Messages.text("rivet.core.skin_not_found_efd2256f"));}return null;});
 }
 public long checked(UUID owner,String source)throws Exception{return db.communityTransaction(()->{try(var q=db.connection().prepareStatement("SELECT checked FROM skin_profiles WHERE owner=? AND source=?")){q.setObject(1,owner);q.setString(2,source);try(var r=q.executeQuery()){return r.next()?r.getLong(1):0;}}});}
 public void fallback(UUID owner,String source,byte[] data,boolean slim,long now)throws Exception{byte[] png=data==null?null:SkinImage.normalize(data,1024*1024);String hash=png==null?null:Hashes.sha256(png);db.communityTransaction(()->{lock();profile(owner);if(png!=null)image(hash,png);try(var q=db.connection().prepareStatement("UPDATE skin_profiles SET fallback=?,slim=?,source=?,checked=? WHERE owner=?")){q.setString(1,hash);q.setBoolean(2,slim);q.setString(3,source);q.setLong(4,now);q.setObject(5,owner);q.executeUpdate();}clean();return null;});}
}
